        {"param": "data_width", "low": 11, "high": 28, "choices": null},
        {"param": "n_iter", "low": 10, "high": 30, "choices": null},
        {"param": "angle_guard", "low": -2, "high": 4, "choices": null},
        {"param": "frac_guard", "low": 0, "high": 4, "choices": null},
        {"param": "rounding", "low": null, "high": null, "choices": ["trunc", "round"]}
      ],
      "family": "iterative",
      "budget_share": 0.95
    },
    {
      "why": "Strictly dominated: identical bit-accurate results to iterative but k chained micro-rotations multiply the datapath, so it cannot win on luts_plus_ffs for any accuracy point, and throughput is not a binding constraint here. Token share only, restricted to the small-k / low-area corner where it is closest to iterative, to confirm the 0/17 front result before the reserved full-range mapping is spent elsewhere.",
      "ranges": [
        {"param": "data_width", "low": 11, "high": 18, "choices": null},
